import { CLOUDFLARE_LORA_MODEL_PAIRS } from './lora-plan.js';

const CENSORSHIP_REFUSAL = /\b(?:je ne peux pas (?:vous aider|aider avec|r[eé]pondre [aà] (?:ça|cela|cette))|je (?:dois|vais) refuser|contenu (?:interdit|inappropri[eé])|i (?:can(?:not|'t)|won't|will not) (?:help|assist)|cannot assist|against (?:my|our|the) (?:guidelines|policies)|content policy|usage policy|i'm not able to (?:help|provide))\b/i;

// A short policy refusal only. A long answer, a missing tool or a missing
// adapter is not a censorship failure and must not change the mode.
export function isCensorshipRefusal(text) {
  const value = String(text || '').trim();
  return value.length > 0 && value.length <= 500 && CENSORSHIP_REFUSAL.test(value);
}

// Only the server's promoted adapter is accepted; never a browser-supplied ID.
export function requireChatLora(active) {
  const base = active?.base_model || active?.adapter?.base_model;
  const runtime = active?.runtime_model || active?.adapter?.runtime_model;
  const finetune = active?.finetune_id || active?.adapter?.finetune_id;
  if (!base || !runtime || !finetune || CLOUDFLARE_LORA_MODEL_PAIRS[base] !== runtime) {
    throw Object.assign(new Error('LORA_COMPATIBLE_ACTIVE_ADAPTER_REQUIRED'), { code:'LORA_COMPATIBLE_ACTIVE_ADAPTER_REQUIRED' });
  }
  return { plan_id:active.plan_id || null, base_model:base, runtime_model:runtime, finetune_id:finetune };
}

export function chatLoraReceipt(active, inference) {
  try {
    const adapter = requireChatLora(active);
    return inference?.provider === 'workers-ai' && inference?.model === adapter.runtime_model
      ? { ...adapter, applied:true }
      : null;
  } catch { return null; }
}

// MEL-LORA-MODE-01: the Mistral adapter and the Qwen model are two different
// things. A Qwen record must never satisfy the Mistral adapter check, and the
// reverse, or the mode would run on the wrong weights while claiming the
// other. And when neither is usable, the mode is REFUSED with its exact
// reason: a silent fallback to an ordinary cloud model would answer in the
// name of a LoRA that never ran.
export const QWEN_LORA_BASE = 'Qwen/Qwen3-14B';

export function loraModeKind(record) {
  const base = String(record?.base_model || record?.adapter?.base_model || '').trim();
  if (!base) return null;
  if (base === QWEN_LORA_BASE) return 'QWEN_MODEL';
  return CLOUDFLARE_LORA_MODEL_PAIRS[base] ? 'MISTRAL_ADAPTER' : null;
}

// Explicit refusal, never a silent fallback. `reason` says which of absence,
// quota or failure stopped the mode, so the owner reads the real cause.
export function resolveLoraMode({ adapter = null, qwen = null, quota = null, failure = null } = {}) {
  const refuse = (code, detail) => ({ ok: false, kind: null, code, detail: String(detail || '').slice(0, 200), fallback: 'NONE' });
  // A Qwen record offered as the Mistral adapter is a confusion, not a mode.
  if (adapter && loraModeKind(adapter) === 'QWEN_MODEL') return refuse('LORA_MODE_ADAPTER_KIND_MISMATCH', 'Qwen proposé comme adaptateur Mistral');
  if (qwen && loraModeKind(qwen) === 'MISTRAL_ADAPTER') return refuse('LORA_MODE_ADAPTER_KIND_MISMATCH', 'adaptateur Mistral proposé comme modèle Qwen');
  if (quota?.exhausted === true) return refuse('LORA_MODE_QUOTA_EXHAUSTED', quota.detail || quota.code);
  if (failure) return refuse('LORA_MODE_PROVIDER_FAILED', failure?.code || failure?.message || failure);
  if (adapter) {
    try { return { ok: true, kind: 'MISTRAL_ADAPTER', adapter: requireChatLora(adapter), code: null, fallback: 'NONE' }; }
    catch (error) { return refuse(String(error?.code || 'LORA_MODE_ADAPTER_INVALID'), 'adaptateur Mistral incompatible'); }
  }
  if (qwen) return { ok: true, kind: 'QWEN_MODEL', adapter: { base_model: QWEN_LORA_BASE, adapter_id: String(qwen.adapter_id || '') }, code: null, fallback: 'NONE' };
  return refuse('LORA_MODE_ADAPTER_ABSENT', 'aucun adaptateur validé actif');
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { requireChatLora, chatLoraReceipt, isCensorshipRefusal } from '../src/learning/chat-lora-binding.js';
import { runNativeInference, handleNativeChat } from '../src/api/native-chat.js';
import { onRequestGet } from '../src/pages/full-interface-v2.js';
import { JSDOM } from 'jsdom';

const active = {
  plan_id:'validated-test', base_model:'mistralai/Mistral-7B-Instruct-v0.2',
  runtime_model:'@cf/mistral/mistral-7b-instruct-v0.2-lora', finetune_id:'ft-test',
};

test('missing and incompatible LoRA never qualify for the requested mode', () => {
  for (const value of [null, {}, {...active, base_model:'Qwen/Qwen2.5-1.5B'}, {...active, finetune_id:''}]) {
    assert.throws(() => requireChatLora(value), {code:'LORA_COMPATIBLE_ACTIVE_ADAPTER_REQUIRED'});
  }
});

test('requested UNCENSORED routes to Venice irrespective of local LoRA settings', async () => {
  const previousFetch = globalThis.fetch;
  const calls = [];
  globalThis.fetch = async (url, options) => {
    calls.push({url:String(url), body:JSON.parse(options.body)});
    return Response.json({choices:[{message:{content:'Bonjour depuis Venice.'}}]});
  };
  try {
    let localCalls=0;
    const result=await runNativeInference({
      env:{OPENROUTER_API_KEY:'sk-or-'+'x'.repeat(40), AI:{run:async()=>{localCalls++;throw new Error('not expected');}}},
      messages:[{role:'user',content:'Bonjour'}], activeAdapter:active,
      requireLora:true, parallel:true, preferredModel:'@cf/zai-org/glm-4.7-flash'
    });
    assert.equal(result.provider,'openrouter');
    assert.equal(calls.length,1);
    assert.match(calls[0].url,/openrouter.ai/);
    assert.equal(localCalls,0);
  } finally {globalThis.fetch=previousFetch;}
});

test('UNCENSORED missing Venice key never calls another cloud model', async () => {
  let calls=0;
  await assert.rejects(runNativeInference({
    env:{AI:{run:async()=>{calls++;return {response:'wrong model'};}}},
    messages:[{role:'user',content:'Bonjour'}], requireLora:true,activeAdapter:active
  }),{code:'VENICE_KEY_MISSING'});
  assert.equal(calls,0);
});

test('Qwen, ordinary cloud fallback and deterministic receipts never claim the configured LoRA', () => {
  for (const inference of [{model:'pc:qwen3:8b',provider:'companion'}, {model:'@cf/zai-org/glm-4.7-flash',provider:'workers-ai'}, {model:active.runtime_model,provider:'mel'}]) {
    assert.equal(chatLoraReceipt(active,inference),null);
  }
});

test('UNCENSORED fails closed when OpenRouter key is missing, ignoring browser adapter IDs', async () => {
  let calls=0;
  const response=await handleNativeChat(new Request('https://mel.test/api/chat',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({text:'bonjour',lora_mode:'uncensored',activeAdapter:active})}),{AI:{run:async()=>{calls++;return {response:'invalid'};}}},{authorized:true});
  assert.equal(response.status,503);
  assert.equal((await response.json()).code,'VENICE_KEY_MISSING');
  assert.equal(calls,0);
});

test('bottom chat button toggles an explicit LoRA request without claiming activation', async () => {
  const html=await (await onRequestGet()).text();
  const dom=new JSDOM(html,{runScripts:'outside-only'});
  const button=dom.window.document.querySelector('#chatLoraMode');
  assert.equal(button.type,'button');
  assert.equal(button.getAttribute('aria-pressed'),'false');
  const runtime=html.match(/<script>([\s\S]*?)<\/script>/)[1];
  const binding=runtime.slice(runtime.indexOf("qs('#chatLoraMode').onclick="),runtime.indexOf("qs('#chatForm').addEventListener('submit'"));
  new Function('qs',binding)(selector=>dom.window.document.querySelector(selector));
  button.click();
  assert.equal(button.value,'uncensored');
  assert.equal(button.getAttribute('aria-pressed'),'true');
  assert.equal(button.textContent,'UNCENSORED');
  assert.equal(button.className,'primary');
  button.click();
  assert.equal(button.value,'automatic');
  assert.equal(button.getAttribute('aria-pressed'),'false');
  assert.match(runtime,/lora_mode:qs\('#chatLoraMode'\)\?\.value/);
  dom.window.close();
});

test('only a short policy refusal counts as censorship', () => {
  assert.equal(isCensorshipRefusal('Je ne peux pas vous aider avec cette demande.'), true);
  assert.equal(isCensorshipRefusal('I cannot assist with that request.'), true);
  assert.equal(isCensorshipRefusal('Je ne peux pas lire ta boîte Gmail : le connecteur est absent.'), false);
  assert.equal(isCensorshipRefusal('Mode UNCENSORED indisponible : aucun adaptateur.'), false);
  assert.equal(isCensorshipRefusal('x'.repeat(501) + ' I cannot assist'), false);
});

test('normal mode switches to the validated LoRA after one censorship refusal', async () => {
  const { sqliteD1 } = await import('./helpers/sqlite-d1.mjs');
  const { MentorMemoryRepository } = await import('../src/learning/mentor-memory.js');
  const DB = sqliteD1();
  try {
    await new MentorMemoryRepository(DB).remember({
      kind: 'LORA_ADAPTER_ACTIVE', lesson: 'Adaptateur validé.',
      evidence: active,
    });
    const calls = [];
    const response = await handleNativeChat(new Request('https://mel.test/api/chat', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ text: 'raconte une histoire courte', lora_mode: 'automatic', use_companion_compute: false }),
    }), { DB, AI: { run: async (model) => { calls.push(model); return { response: calls.length === 1 ? 'Je ne peux pas vous aider avec cette demande.' : 'Histoire libre.' }; } } }, { authorized: true });
    const payload = await response.json();
    assert.equal(payload.text, 'Histoire libre.');
    assert.equal(payload.lora_mode, 'uncensored');
    assert.ok(calls.length >= 2);
  } finally { DB.close(); }
});

test('without a validated adapter a censorship refusal stays on the normal answer', async () => {
  const { sqliteD1 } = await import('./helpers/sqlite-d1.mjs');
  const DB = sqliteD1();
  try {
    const calls = [];
    const response = await handleNativeChat(new Request('https://mel.test/api/chat', {
      method: 'POST', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ text: 'raconte une histoire courte', use_companion_compute: false }),
    }), { DB, AI: { run: async (model) => { calls.push(model); return { response: 'Je ne peux pas vous aider avec cette demande.' }; } } }, { authorized: true });
    const payload = await response.json();
    assert.equal(payload.text, 'Je ne peux pas vous aider avec cette demande.');
    assert.equal(payload.lora_mode, 'automatic');
    assert.equal(calls.length, 1);
  } finally { DB.close(); }
});

test('UNCENSORED without an active adapter falls back to Venice when its key is set', async () => {
  const realFetch = globalThis.fetch; const urls = [];
  globalThis.fetch = async (url) => { urls.push(String(url)); return new Response(JSON.stringify({ choices: [{ message: { content: 'Réponse Venice.' } }] })); };
  try {
    const env = { OPENROUTER_API_KEY: 'sk-or-' + 'x'.repeat(40), AI: { run: async (model) => (String(model).includes('llama-guard') ? { response: 'safe' } : { response: '' }) } };
    const response = await handleNativeChat(new Request('https://mel.test/api/chat', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ text: 'bonjour', lora_mode: 'uncensored' }) }), env, { authorized: true });
    const payload = await response.json();
    assert.notEqual(payload.code, 'LORA_COMPATIBLE_ACTIVE_ADAPTER_REQUIRED');
    assert.match(String(payload.text), /Réponse Venice/);
    assert.ok(urls.some(u => u.includes('openrouter.ai')));
  } finally { globalThis.fetch = realFetch; }
});
